public int findLargestSubstring(List<String> strings) {
    if (strings == null || strings.isEmpty()) {
        return 0;
    }
    // Find the minimum length among all strings
    int minLen = Integer.MAX_VALUE;
    for (String s : strings) {
        if (s == null) {
            return 0;
        }
        minLen = Math.min(minLen, s.length());
    }
    if (minLen == 0) {
        return 0;
    }
    String first = strings.get(0);
    // Try lengths from minLen down to 1
    for (int len = minLen; len >= 1; len--) {
        // Generate all substrings of length len from the first string
        for (int i = 0; i <= first.length() - len; i++) {
            String sub = first.substring(i, i + len);
            String rev = new StringBuilder(sub).reverse().toString();
            boolean ok = true;
            // Check all strings
            for (String s : strings) {
                if (!(s.contains(sub) || s.contains(rev))) {
                    ok = false;
                    break;
                }
            }
            if (ok) {
                return len;
            }
        }
    }
    return 0;
}

