  tree = new ArrayList<>();
  res = new int[n];
  Arrays.fill(res, -1);
  for (int i = 0; i < n; ++i) tree.add(new HashSet<>());
  for (int[] e : edges) {
    tree.get(e[0]).add(e[1]);
